import Foundation

// Only the fixed node format generated by this app can be losslessly re-exported.
enum NodeImport {
    static func parse(_ text: String) throws -> DeployedNode {
        let document = try Configuration.document(Configuration.importText(text))
        let node: DeployedNode
        if let native = document[NativeXrayProfile.key] as? [String: Any], let outbound = (native["outbounds"] as? [[String: Any]])?.first(where: { ($0["protocol"] as? String)?.lowercased() == "vless" }),
           let settings = outbound["settings"] as? [String: Any], let server = (settings["vnext"] as? [[String: Any]])?.first,
           let user = (server["users"] as? [[String: Any]])?.first, let stream = outbound["streamSettings"] as? [String: Any],
           stream["security"] as? String == "reality", ["tcp", "raw"].contains(stream["network"] as? String ?? "tcp"),
           let reality = stream["realitySettings"] as? [String: Any], let address = server["address"] as? String, let port = NodeSharing.portNumber(server["port"]),
           let uuid = user["id"] as? String, let key = reality["password"] as? String ?? reality["publicKey"] as? String, let sid = reality["shortId"] as? String, let name = reality["serverName"] as? String,
           user["flow"] as? String == "xtls-rprx-vision" {
            let tcp = stream["tcpSettings"] as? [String: Any] ?? stream["rawSettings"] as? [String: Any] ?? [:]
            guard (settings["vnext"] as? [[String: Any]])?.count == 1, (server["users"] as? [[String: Any]])?.count == 1,
                  (native["outbounds"] as? [[String: Any]])?.filter({ ($0["protocol"] as? String)?.lowercased() == "vless" }).count == 1,
                  outbound["proxySettings"] == nil, stream["sockopt"] == nil, (outbound["mux"] as? [String: Any])?["enabled"] as? Bool != true,
                  user["encryption"] == nil || user["encryption"] as? String == "none",
                  (reality["fingerprint"] as? String ?? "chrome") == "chrome",
                  reality["spiderX"] == nil || reality["spiderX"] as? String == "/",
                  reality["mldsa65Verify"] == nil,
                  ((tcp["header"] as? [String: Any])?["type"] as? String ?? "none") == "none"
            else { throw ProxyError("节点含自定义链式、加密或传输参数，请使用原配置。") }
            node = DeployedNode(server: address, port: port, uuid: uuid, publicKey: key, shortId: sid, serverName: name)
        } else if let value = (document["proxies"] as? [[String: Any]])?.first, value["type"] as? String == "vless",
                  value["flow"] as? String == "xtls-rprx-vision", let reality = value["reality-opts"] as? [String: Any],
                  let address = value["server"] as? String, let port = NodeSharing.portNumber(value["port"]), let uuid = value["uuid"] as? String,
                  let key = reality["public-key"] as? String, let sid = reality["short-id"] as? String, let name = value["servername"] as? String {
            guard (document["proxies"] as? [[String: Any]])?.count == 1,
                  (value["network"] as? String ?? "tcp") == "tcp", value["tls"] as? Bool == true,
                  value["dialer-proxy"] == nil, value["plugin"] == nil, value["packet-encoding"] == nil,
                  value["skip-cert-verify"] as? Bool != true,
                  (value["client-fingerprint"] as? String ?? "chrome") == "chrome",
                  value["ws-opts"] == nil, value["grpc-opts"] == nil, value["http-opts"] == nil
            else { throw ProxyError("节点含自定义链式或传输参数，请使用原配置。") }
            node = DeployedNode(server: address, port: port, uuid: uuid, publicKey: key, shortId: sid, serverName: name)
        } else { throw ProxyError("当前导入支持单个 TCP VLESS / Reality / Vision 节点。其他协议可在网页后台管理。") }
        var request = ServerRequest(); request.host = node.server; request.nodePort = node.port; request.serverName = node.serverName
        if request.sshPort == node.port { request.sshPort = 2222 }
        try node.validate(expected: request)
        return node
    }
}
